#!/bin/bash
# Сторож Charlotte v2.8 — тишина огня отличает поломку от сознательного отказа.
# v2.4: дедуп 60мин на 🟡. v2.5: порог 6ч считается от ВОЗРАСТА ТИШИНЫ (засев), не от аптайма.
# v2.8 (28.08 01:25Z): ШЕСТЬ признаков проверены по эталону — НИ ОДИН не отличает поломку от
#   пустого рынка: арм-скипы (2003), '+вне досягаемости' (37), 'targets=0' (152/518), 'доска
#   armed' (1 за 5ч против 0), ТЕМП NB (в эталоне 95-266/30мин — как в 41 из 48 обычных окон
#   суток; мой «разрыв 64x» был сравнением ДВУХ ТОЧЕК, а не с распределением), прямые признаки
#   (0 трейсбеков, 0 CRITICAL, 0 падений, заморозка 1/153 = норма). Тревога больше НЕ СОВЕТУЕТ
#   судить по этим числам — она честно называет свой предел и отсылает к ИСХОДУ В ЦЕПИ
#   (призовая тревога: пропустили ли мы приз). Escape по NB убран — он опирался на опровергнутое.
# v2.7 (28.08 01:05Z): 💀 на пустом рынке била КАЖДЫЕ 15 мин — тревога, кричащая на здоровом
#   боте, обесценивает себя. Теперь повтор не чаще часа, НО мгновенно при РОСТЕ подписи
#   поломки (NB): чувствительность к настоящей аварии ВЫШЕ прежней, шум вчетверо ниже.
#   Стенды: пустой рынок 2 тревоги за 2ч вместо 8; начало поломки внутри дедупа — крик сразу;
#   углубление 191->400 — крик сразу; держащаяся поломка — 2 за 2ч, не 8.
# v2.6 (28.08 00:45Z): 💀 сработала на ЗДОРОВОМ боте — рынок опустел (targets=0), отказов по
#   полу не печаталось, и «нет отказов» прочиталось как поломка.
#
# ЧЕТЫРЕ ПОПЫТКИ ПОСТРОИТЬ ДИСКРИМИНАТОР — ТРИ ОПРОВЕРГНУТЫ ЭТАЛОНОМ (окно реальной поломки
# 27.08 08:14-13:29, где сторож ОБЯЗАН кричать). Числа за то окно / за 30 мин здоровья:
#   'арм НЕ ВЗВЁЛСЯ' (любая причина):  2003  -> правило заглушило бы аварию
#   '+ вне досягаемости':                37  -> заглушило бы в части окон
#   'targets=0':                    152/518  -> встречается и там, и тут (13/28) => заглушило бы
#   'проба не собралась':          2003 (6.4/мин) против 3 (0.1/мин) => различает ТЕМП, не факт
# ВЫВОД: правила на ПРИСУТСТВИИ признака не работают. Поэтому 💀 НИЧЕМ НЕ ГЛУШИТСЯ, а НЕСЁТ
# числа и эталон в тексте — читающий судит за один взгляд. Любое будущее изменение признака
# прогонять по окну 08:14-13:29 ПРЕЖДЕ, чем ставить.
#
# 🔴 (порог 6ч) теперь честно называет себя ГИПОТЕЗОЙ: проверять свежим замером близости целей.
# Замеры вынесены в charlotte_seed.sh и charlotte_probe.sh (едут через bash -s, вложенных
# кавычек нет). НЕ ПРАВИТЬ ЭТОТ ФАЙЛ НА ХОДУ: bash читает лениво, правка сдвигает смещение
# дескриптора (поймано 27.08: pos 5688 при размере 7029). Менять -> сразу перезапуск сторожа.
( while true; do ssh -o BatchMode=yes -o ConnectTimeout=15 -o ServerAliveInterval=30 -o ServerAliveCountMax=3 root@185.173.146.134 "journalctl -u liquidator-bot -f --no-pager -o cat" 2>/dev/null | grep -E --line-buffered "SPECFIRE WIN|PlanExecuted|REFUSAL-LOSS|Traceback|CRITICAL|SamePoolInfeasible|§9 группа НЕ собрана|group_refused=[1-9]|transport_reject=[1-9]|fast-lane выключен|ЗАМОРОЖЕН|PREDICT МЁРТВ|kill-switch.*(СРАБОТ|LOSS|СТОП)|Main process exited|Started Liquidator|collect handler fail|арм НЕ ВЗВЁЛСЯ|несобираема|HR bid|выход сломан|RCPT-SHADOW РАСХОЖДЕНИЕ|перехват детонатора ОТКЛОНЁН|доска armed" | grep -vE "книжка выручки" | awk '{ cls=""; if ($0 ~ /Traceback/) cls="tb"; else if ($0 ~ /§9 группа НЕ собрана/) cls="g9"; else if ($0 ~ /collect handler fail/) cls="chf"; else if ($0 ~ /арм НЕ ВЗВЁЛСЯ/) cls="arm"; else if ($0 ~ /несобираема/) cls="ub"; else if ($0 ~ /ЗАМОРОЖЕН/) cls="idx"; else if ($0 ~ /перехват детонатора ОТКЛОНЁН/) cls="det"; else if ($0 ~ /доска armed/) cls="armed"; if (cls != "") { c=systime(); if (c-t[cls]<3600) { n[cls]++; next } t[cls]=c; n[cls]++; print $0 " [дедуп 60мин, счёт " cls ": " n[cls] "]"; fflush(); next } print; fflush() }'; echo "WATCHDOG: ssh-хвост журнала Charlotte оборвался, реконнект через 30с"; sleep 30; done ) & ( S=0; LAST=0; FIRED=0; SEEDM=-1; LASTD=0; SR=$(ssh -o BatchMode=yes -o ConnectTimeout=15 root@185.173.146.134 bash -s < /home/claude-agent/.fleet-watch/charlotte_seed.sh 2>/dev/null); set -- $SR; JL=${1:-0}; PTS=${2:-}; NOWS=$(date +%s); if [ "$JL" -gt 0 ] && [ -n "$PTS" ]; then SEEDM=$(( (NOWS - PTS) / 60 )); elif [ "$JL" -gt 0 ]; then SEEDM=1440; else SEEDM=-1; fi; echo "WATCHDOG v2.8 поднят: засев тишины ${SEEDM}мин (строк журнала за 24ч: $JL; -1 = журнал не покрывает)"; while true; do sleep 900; R=$(ssh -o BatchMode=yes -o ConnectTimeout=15 root@185.173.146.134 bash -s < /home/claude-agent/.fleet-watch/charlotte_probe.sh 2>/dev/null); set -- $R; P=${1:-}; A=${2:-0}; D=${3:-0}; ARMED=${4:-0}; Z=${5:-0}; NB=${6:-0}; NR=${7:-0}; NEAR=${8:--}; NOW=$(date +%s); if [ -n "$P" ] && [ "$P" -eq 0 ] && [ "$A" -gt 0 ]; then if [ "$D" -gt 0 ]; then S=$((S+1)); if [ "$SEEDM" -ge 0 ]; then M=$((SEEDM + S*15)); SRC="засев+наблюдение"; else M=$((S*15)); SRC="ТОЛЬКО наблюдение сторожа, возраст тишины до старта НЕИЗВЕСТЕН"; fi; if [ $((NOW-LAST)) -ge 3600 ]; then echo "🟡 тишина ОБЪЯСНЕНА: проб=0, $D отказов по полу досягаемости (ближайшая цель $NEAR) — доска цела, достижимых целей нет. Держится ~${M}мин из 360 до порога ($SRC); человеку делать нечего [дедуп 60мин]"; LAST=$NOW; fi; if [ "$M" -ge 360 ] && [ "$FIRED" -eq 0 ]; then echo "🔴 ПОРОГ ПРОБИТ: объяснённая тишина ${M}мин >= 360 ($SRC). По правилу самой тревоги «список кандидатов не работает» — но это ГИПОТЕЗА: проверить свежим замером близости целей И призовой тревогой (были ли призы, которые мы пропустили). Ближайшая цель $NEAR"; FIRED=1; fi; else S=0; SEEDM=0; FIRED=0; if [ $((NOW-LASTD)) -ge 3600 ]; then echo "💀 ТИШИНА ОГНЯ: за 30 мин проб=0, армов=$A, досок=$ARMED, отказов по полу=0 | targets=0: $Z из $A | «проба не собралась»: $NB | «вне досягаемости»: $NR | ближайшая $NEAR [дедуп 60мин]. ЧЕСТНО О ПРЕДЕЛЕ ЭТОЙ ТРЕВОГИ (замерено 28.08): по журналу бота поломка НЕОТЛИЧИМА от пустого рынка. В эталонном окне аварии 27.08 08:14-13:29 было 0 трейсбеков, 0 CRITICAL, 0 падений службы, заморозка индекса 1 из 153 окон (штатные 0.65%), а NB там 95-266 за 30мин — ровно как в 41 из 48 обычных окон суток. Шесть признаков проверены, НИ ОДИН не разделяет. РАЗДЕЛЯЕТ ТОЛЬКО ИСХОД В ЦЕПИ: смотреть призовую тревогу — были ли ликвидации Morpho, которые мы пропустили. Нет призов ⇒ молчание было верным"; LASTD=$NOW; fi; fi; else S=0; SEEDM=0; FIRED=0; fi; done ) & wait